def config_value(text: str, key: str) -> str:
    """Return the value for `key` in per-line `name=value` config text.

    Each line holds one `name=value` pair. Splits on the first '='.
    Returns an empty string when the key is absent. Does not read files.
    """
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if sep and name == key:
            return value
    return ""


def test_config_value_returns_present_value() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_config_value_returns_empty_string_when_absent() -> None:
    assert config_value("host=localhost\nport=8080", "user") == ""


def test_config_value_returns_empty_string_for_empty_text() -> None:
    assert config_value("", "host") == ""


def test_config_value_splits_on_first_equals() -> None:
    assert config_value("expr=a=b=c", "expr") == "a=b=c"


def test_config_value_first_match_wins_on_duplicate_keys() -> None:
    assert config_value("mode=fast\nmode=slow", "mode") == "fast"
